-- Mover panel login by phone + one-time SMS code, for movers who have no email (lib/moverOtp.ts, /movers/login?by=phone).
--
-- How it works without a Supabase SMS provider:
--  * The admin opens "phone access" for a mover. That creates a Supabase Auth user with an internal, never-mailed address
--    (phone-<digits>@phone.movematch.co.il) and a random password nobody knows.
--  * The mover types their phone, gets a 6-digit code by SMS (10 minutes, 5 wrong tries, max 5 codes per hour, 1 per minute).
--  * On a correct code the database sets a NEW random password (generated by the server, used once, never shown) and the
--    server signs in with the normal password grant. So every login is a fresh code; there is no password to forget or change.
--  * Only phone-only accounts can sign in this way: an email account's own password is never touched. If the admin later
--    gives the mover an email login (mm_admin_set_mover_login), the account moves to that email and phone login stops.

create table if not exists movematch.mover_otps (
  id bigint generated always as identity primary key,
  mover_id uuid not null references movematch.movers(id) on delete cascade,
  code_hash text not null,
  created_at timestamptz not null default now(),
  expires_at timestamptz not null,
  attempts int not null default 0,
  used_at timestamptz
);
create index if not exists mover_otps_mover_idx on movematch.mover_otps (mover_id, created_at desc);
alter table movematch.mover_otps enable row level security;
revoke all on movematch.mover_otps from anon, authenticated;

create or replace function movematch.phone_login_email(p_phone text) returns text
language sql immutable set search_path = '' as $$ select 'phone-' || p_phone || '@phone.movematch.co.il' $$;

-- ── Admin: give a mover phone-only panel access. Idempotent. ──
create or replace function public.mm_admin_set_mover_phone_login(p_secret text, p_mover uuid) returns jsonb
language plpgsql security definer set search_path = '' as $$
declare m movematch.movers; v_email text; v_uid uuid;
begin
  perform public.mm_check_admin(p_secret);
  select * into m from movematch.movers where id = p_mover;
  if m.id is null then raise exception 'not found'; end if;
  if m.auth_user_id is not null then
    if exists (select 1 from auth.users where id = m.auth_user_id and email like '%@phone.movematch.co.il') then
      return jsonb_build_object('phone', m.phone, 'existing', true);
    end if;
    raise exception 'has email login';
  end if;
  v_email := movematch.phone_login_email(m.phone);
  delete from auth.users where lower(email) = v_email; -- leftover from an earlier revoke
  v_uid := gen_random_uuid();
  insert into auth.users (instance_id, id, aud, role, email, encrypted_password, email_confirmed_at, raw_app_meta_data, raw_user_meta_data,
    created_at, updated_at, confirmation_token, recovery_token, email_change, email_change_token_new)
  values ('00000000-0000-0000-0000-000000000000', v_uid, 'authenticated', 'authenticated', v_email,
    extensions.crypt(encode(extensions.gen_random_bytes(24), 'hex'), extensions.gen_salt('bf', 10)), now(),
    '{"provider":"email","providers":["email"]}'::jsonb, jsonb_build_object('mover_id', m.id, 'phone_login', true), now(), now(), '', '', '', '');
  insert into auth.identities (user_id, provider_id, identity_data, provider, last_sign_in_at, created_at, updated_at)
  values (v_uid, v_uid::text, jsonb_build_object('sub', v_uid::text, 'email', v_email, 'email_verified', true), 'email', now(), now(), now());
  update movematch.movers set auth_user_id = v_uid, must_change_password = false where id = m.id;
  return jsonb_build_object('phone', m.phone, 'existing', false);
end $$;

-- ── Request a code (server-only). Returns the mover's first name when a code may be sent, else null (same answer to the visitor). ──
create or replace function public.mm_mover_otp_request(p_secret text, p_phone text, p_code_hash text) returns jsonb
language plpgsql security definer set search_path = '' as $$
declare m movematch.movers;
begin
  perform public.mm_check_admin(p_secret);
  select mv.* into m from movematch.movers mv join auth.users u on u.id = mv.auth_user_id
    where mv.phone = p_phone and mv.status = 'approved' and u.email like '%@phone.movematch.co.il';
  if m.id is null then return null; end if;
  if exists (select 1 from movematch.mover_otps where mover_id = m.id and created_at > now() - interval '60 seconds') then return jsonb_build_object('wait', true); end if;
  if (select count(*) from movematch.mover_otps where mover_id = m.id and created_at > now() - interval '1 hour') >= 5 then return jsonb_build_object('wait', true); end if;
  update movematch.mover_otps set used_at = now() where mover_id = m.id and used_at is null; -- only the newest code works
  insert into movematch.mover_otps (mover_id, code_hash, expires_at) values (m.id, p_code_hash, now() + interval '10 minutes');
  return jsonb_build_object('name', split_part(m.name, ' ', 1));
end $$;

-- ── Check a code (server-only). On success sets a one-use random password and returns the internal login email. ──
create or replace function public.mm_mover_otp_verify(p_secret text, p_phone text, p_code_hash text, p_password text) returns text
language plpgsql security definer set search_path = '' as $$
declare m movematch.movers; o movematch.mover_otps; v_email text;
begin
  perform public.mm_check_admin(p_secret);
  if length(coalesce(p_password, '')) < 24 then raise exception 'short password'; end if;
  select mv.* into m from movematch.movers mv join auth.users u on u.id = mv.auth_user_id
    where mv.phone = p_phone and mv.status = 'approved' and u.email like '%@phone.movematch.co.il';
  if m.id is null then return null; end if;
  select * into o from movematch.mover_otps where mover_id = m.id and used_at is null and expires_at > now()
    order by created_at desc limit 1 for update;
  if o.id is null or o.attempts >= 5 then return null; end if;
  if o.code_hash <> p_code_hash then
    update movematch.mover_otps set attempts = attempts + 1 where id = o.id;
    return null;
  end if;
  update movematch.mover_otps set used_at = now() where id = o.id;
  update auth.users set encrypted_password = extensions.crypt(p_password, extensions.gen_salt('bf', 10)), banned_until = null, updated_at = now()
    where id = m.auth_user_id returning email into v_email;
  return v_email;
end $$;

revoke execute on function public.mm_admin_set_mover_phone_login(text, uuid), public.mm_mover_otp_request(text, text, text),
  public.mm_mover_otp_verify(text, text, text, text) from public;
grant execute on function public.mm_admin_set_mover_phone_login(text, uuid), public.mm_mover_otp_request(text, text, text),
  public.mm_mover_otp_verify(text, text, text, text) to anon;
